#ifndef EQEMU_HOUSING_GUILD_TROPHIES_DB_H
#define EQEMU_HOUSING_GUILD_TROPHIES_DB_H
#include "guild_trophy_sources.h"
#include "guild_favor.h"
namespace Housing::GuildTrophies {
using Error=LiveItems::Error;using Failure=TrophyBenefits::Detail::Failure;
struct Subject {uint32_t character=0,account=0,guild=0,rank=0,favor=0;bool opt_in=false,ordinary_opt_in=false;uint32_t donations=0;};
inline Subject MemberUnderTransaction(Database& db,AuthenticatedPurchaser actor){
 auto rows=Q(db,"SELECT c.id,c.account_id,c.deleted_at,m.guild_id,m.`rank`,m.trophy_enable,g.leader,g.favor,m.tribute_enable,m.total_tribute FROM character_data c JOIN account a ON a.id=c.account_id JOIN guild_members m ON m.char_id=c.id JOIN guilds g ON g.id=m.guild_id WHERE c.id="+std::to_string(actor.character_id)+" FOR UPDATE");
 if(rows.RowCount()!=1)throw Failure{Error::Unauthorized};auto r=rows.begin();const auto rank=AccessPolicy::NativeGuildRankFromServer(Number(r[4]));if(!rank||!AccessPolicy::PositiveIdentity(Number(r[3]))||r[2]||Number(r[1])!=actor.account_id||Number(r[5])>1||(*rank==1&&Number(r[6])!=actor.character_id))throw Failure{Error::Unauthorized};return {Number(r[0]),Number(r[1]),Number(r[3]),*rank,Number(r[7]),bool(Number(r[5])),bool(Number(r[8])),Number(r[9])};
}
inline bool PermissionUnderTransaction(Database& db,const Subject& actor,uint32_t permission){auto rows=Q(db,"SELECT permission FROM guild_permissions WHERE guild_id="+std::to_string(actor.guild)+" AND perm_id="+std::to_string(permission)+" FOR UPDATE");if(rows.RowCount()!=1||!actor.rank||actor.rank>8)return false;return ((Number(rows.begin()[0])>>(8-actor.rank))&1)!=0;}
inline Catalog DefinitionsUnderTransaction(Database& db){Catalog out;std::map<uint32_t,uint32_t> counts;auto defs=Q(db,"SELECT s.benefit_id,s.placed_item_id,s.source_sha256,s.source_description,t.name,t.unknown,l.level,l.cost,l.item_id,i.id FROM housing_trophy_benefit_sources s JOIN tributes t ON t.id=s.benefit_id AND t.isguild=1 JOIN tribute_levels l ON l.tribute_id=t.id LEFT JOIN items i ON i.id=l.item_id ORDER BY s.benefit_id,l.level FOR UPDATE");if(defs.RowCount()>10000)throw Failure{Error::UnsupportedItem};for(auto r=defs.begin();r!=defs.end();++r){auto id=Number(r[0]);auto& d=out[id];counts[id]=Number(r[5]);if(d.tiers.empty()){d.id=id;d.placed_item_id=Number(r[1]);d.source_sha256=r[2]?r[2]:"";d.name=r[4]?r[4]:"";if(!r[3]||!r[3][0])throw Failure{Error::UnsupportedItem};}if(!r[9])throw Failure{Error::UnsupportedItem};d.tiers.push_back({Number(r[6]),Number(r[7]),Number(r[8])});}for(const auto& [id,d]:out)if(!TrophyBenefits::Valid(d)||counts[id]!=d.tiers.size())throw Failure{Error::UnsupportedItem};return out;}
struct State {GuildTrophyWire::Bank bank;bool enabled=false;uint64_t revision=0;TrophyBenefits::PaidState paid;std::array<std::optional<Source>,4> sources;};
inline State StateUnderTransaction(Database& db,uint32_t guild){auto owner=std::to_string(guild);Q(db,"INSERT INTO housing_guild_trophy_state(guild_id) VALUES ("+owner+") ON DUPLICATE KEY UPDATE guild_id=VALUES(guild_id)");auto rows=Q(db,"SELECT enabled,revision,remaining_ms,paid_until_ms,selection_hash FROM housing_guild_trophy_state WHERE guild_id="+owner+" FOR UPDATE");if(rows.RowCount()!=1||Number(rows.begin()[0])>1)throw Failure{Error::DatabaseFailure};auto r=rows.begin();State out;out.enabled=Number(r[0]);out.revision=std::stoull(r[1]);out.paid={out.enabled,Number(r[2]),std::stoull(r[3]),r[4]?r[4]:""};if(!out.revision)throw Failure{Error::DatabaseFailure};auto selected=Q(db,"SELECT slot,benefit_id,tier,custody_id,house_id,current_host_estate_id,source_digest FROM housing_guild_trophy_selections WHERE guild_id="+owner+" ORDER BY slot FOR UPDATE");if(selected.RowCount()>4)throw Failure{Error::DatabaseFailure};for(auto row=selected.begin();row!=selected.end();++row){auto slot=Number(row[0]);if(slot>=4)throw Failure{Error::DatabaseFailure};out.bank.ids[slot]=Number(row[1]);out.bank.tiers[slot]=int32_t(Number(row[2]));out.sources[slot]=Source{std::stoull(row[3]),std::stoull(row[4]),Number(row[5]),row[6]?row[6]:""};}return out;}
inline void SaveStateUnderTransaction(Database& db,uint32_t guild,const State& state){auto owner=std::to_string(guild);Q(db,"DELETE FROM housing_guild_trophy_selections WHERE guild_id="+owner);for(size_t i=0;i<4;++i)if(state.bank.ids[i]!=UINT32_MAX){if(!state.sources[i])throw Failure{Error::Conflict};const auto& s=*state.sources[i];Q(db,"INSERT INTO housing_guild_trophy_selections(guild_id,slot,benefit_id,tier,custody_id,house_id,current_host_estate_id,source_digest) VALUES ("+owner+","+std::to_string(i)+","+std::to_string(state.bank.ids[i])+","+std::to_string(state.bank.tiers[i])+","+std::to_string(s.custody)+","+std::to_string(s.house)+","+std::to_string(s.estate)+",'"+db.Escape(s.digest)+"')");}Q(db,"UPDATE housing_guild_trophy_state SET enabled="+std::to_string(state.enabled)+",remaining_ms="+std::to_string(state.paid.remaining_ms)+",paid_until_ms="+std::to_string(state.paid.until_ms)+",selection_hash='"+db.Escape(state.paid.selection_hash)+"',revision=revision+1 WHERE guild_id="+owner+" AND revision="+std::to_string(state.revision));}
inline bool PruneUnderTransaction(Database& db,uint32_t guild,State& state,const Catalog& definitions,bool* unreviewed=nullptr){std::set<uint32_t> seen;bool changed=false;for(size_t i=0;i<4;++i){auto id=state.bank.ids[i];if(id==UINT32_MAX)continue;auto d=definitions.find(id);bool valid=d!=definitions.end()&&state.bank.tiers[i]>=0&&size_t(state.bank.tiers[i])<d->second.tiers.size()&&seen.insert(id).second&&state.sources[i];if(valid){const auto& old=*state.sources[i];auto current=SourceProjection(db,guild,old.custody,old.house);valid=bool(current);if(valid&&(current->estate!=old.estate||current->digest!=old.digest)&&unreviewed)*unreviewed=true;}if(!valid){state.bank.ids[i]=UINT32_MAX;state.bank.tiers[i]=0;state.sources[i].reset();changed=true;}}if(changed){state.enabled=false;state.paid={};}return changed;}
inline std::string SelectionHash(const State& state,const Catalog& definitions,const TrophyBenefits::BillingPolicy& policy){std::vector<uint8_t> fingerprint;for(size_t i=0;i<4;++i){TrophyAnchorWire::Detail::Write(fingerprint,state.bank.ids[i]);TrophyAnchorWire::Detail::Write(fingerprint,uint32_t(state.bank.tiers[i]));if(state.bank.ids[i]!=UINT32_MAX){if(!state.sources[i])throw Failure{Error::Conflict};const auto& d=definitions.at(state.bank.ids[i]);const auto& t=d.tiers[state.bank.tiers[i]];TrophyAnchorWire::Detail::Write(fingerprint,t.minimum_level);TrophyAnchorWire::Detail::Write(fingerprint,t.cost);TrophyAnchorWire::Detail::Write(fingerprint,t.stat_item_id);fingerprint.insert(fingerprint.end(),d.source_sha256.begin(),d.source_sha256.end());TrophyAnchorWire::Detail::Write(fingerprint,uint32_t(state.sources[i]->custody));TrophyAnchorWire::Detail::Write(fingerprint,uint32_t(state.sources[i]->custody>>32));TrophyAnchorWire::Detail::Write(fingerprint,uint32_t(state.sources[i]->house));TrophyAnchorWire::Detail::Write(fingerprint,uint32_t(state.sources[i]->house>>32));}}TrophyAnchorWire::Detail::Write(fingerprint,policy.period_ms);TrophyAnchorWire::Detail::Write(fingerprint,policy.policy);fingerprint.insert(fingerprint.end(),policy.source_sha256.begin(),policy.source_sha256.end());std::array<uint8_t,32> hash{};if(!SHA256(fingerprint.data(),fingerprint.size(),hash.data()))throw Failure{Error::DatabaseFailure};const char* hex="0123456789abcdef";std::string out;for(auto c:hash){out+=hex[c>>4];out+=hex[c&15];}return out;}
struct View {Subject member;State state;std::set<uint32_t> available;std::vector<uint32_t> stat_items;std::array<uint32_t,4> stat_item_slots{};uint32_t remaining_ms=0;bool can_modify=false,changed=false;uint32_t changed_member=0;};
enum class Action {Read,Save,OptIn,Modify};
struct Request {Action action=Action::Read;GuildTrophyWire::Bank bank;GuildTrophyWire::OptIn opt_in;uint32_t level=0;std::optional<TrophyBenefits::SelectionLocation> location;};
inline LiveItems::Result<View> ExecuteUnderTransaction(Database& db,const LiveItems::Lease& lease,LiveItems::InventorySessionFence& fence,const Request& request,const Scene::HouseScenePolicy* houses,const InteriorContent::ProfilePolicy* rooms,const CrateBinding::CustodyContext* crates=nullptr){try{
 auto tx=Q(db,"SELECT @@in_transaction");if(tx.RowCount()!=1||Number(tx.begin()[0])!=1||!request.level)return {{},Error::InvalidArgument};auto authenticated=LiveItems::Service::AuthenticateUnderTransaction(db,true,lease,fence);if(!authenticated)return {{},authenticated.error};if(!authenticated.value.pending_key.empty())return {{},Error::PendingApplication};
 auto engines=Q(db,"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND engine='InnoDB' AND table_name IN ('guilds','guild_members','guild_permissions','housing_guild_trophy_state','housing_guild_trophy_selections','housing_guild_trophy_billing_policy','housing_guild_trophy_favor_charges')");if(engines.RowCount()!=1||Number(engines.begin()[0])!=7)return {{},Error::DatabaseFailure};
 View out;out.member=MemberUnderTransaction(db,lease.actor);out.can_modify=PermissionUnderTransaction(db,out.member,25);auto definitions=DefinitionsUnderTransaction(db);out.state=StateUnderTransaction(db,out.member.guild);bool dirty=PruneUnderTransaction(db,out.member.guild,out.state,definitions);
 auto sources=SourcesUnderTransaction(db,lease,fence,out.member.guild,definitions,request.location,houses,rooms,crates);if(!sources)return {{},sources.error};for(const auto& source:sources.value)out.available.insert(source.benefit);
 for(size_t i=0;i<4;++i)if(out.state.bank.ids[i]!=UINT32_MAX&&out.state.sources[i]){auto fresh=std::find_if(sources.value.begin(),sources.value.end(),[&](const auto& source){return source.benefit==out.state.bank.ids[i]&&source.source.custody==out.state.sources[i]->custody&&source.source.house==out.state.sources[i]->house;});if(fresh!=sources.value.end()&&(fresh->source.digest!=out.state.sources[i]->digest||fresh->source.estate!=out.state.sources[i]->estate)){out.state.sources[i]=fresh->source;dirty=true;}}
 if(request.action==Action::Save){if(!out.can_modify)return {{},Error::Unauthorized};std::set<uint32_t> seen;State next=out.state;for(size_t i=0;i<4;++i){auto id=request.bank.ids[i];if(id==UINT32_MAX){next.bank.ids[i]=id;next.bank.tiers[i]=0;next.sources[i].reset();continue;}auto d=definitions.find(id);if(d==definitions.end()||request.bank.tiers[i]<0||size_t(request.bank.tiers[i])>=d->second.tiers.size()||!seen.insert(id).second)return {{},Error::Unauthorized};if(id==out.state.bank.ids[i]&&request.bank.tiers[i]==out.state.bank.tiers[i]&&out.state.sources[i])continue;auto found=std::find_if(sources.value.begin(),sources.value.end(),[&](const auto& s){return s.benefit==id&&s.at_source;});if(found==sources.value.end())return {{},Error::Unauthorized};next.bank.ids[i]=id;next.bank.tiers[i]=request.bank.tiers[i];next.sources[i]=found->source;}
 if(next.bank.ids!=out.state.bank.ids||next.bank.tiers!=out.state.bank.tiers){next.enabled=false;next.paid={};dirty=true;}out.state=std::move(next);
 }
 if(request.action==Action::OptIn){if(request.opt_in.name.empty()||request.opt_in.name.size()>63)return {{},Error::InvalidArgument};auto target=Q(db,"SELECT c.id,c.deleted_at,m.guild_id,m.tribute_enable,m.trophy_enable FROM character_data c JOIN guild_members m ON m.char_id=c.id WHERE c.name='"+db.Escape(request.opt_in.name)+"' FOR UPDATE");if(target.RowCount()!=1||target.begin()[1]||Number(target.begin()[2])!=out.member.guild)return {{},Error::Unauthorized};const auto id=Number(target.begin()[0]);if(id!=lease.actor.character_id&&!PermissionUnderTransaction(db,out.member,24))return {{},Error::Unauthorized};Q(db,"UPDATE guild_members SET trophy_enable="+std::to_string(request.opt_in.enabled)+" WHERE guild_id="+std::to_string(out.member.guild)+" AND char_id="+std::to_string(id));out.changed_member=id;out.changed=true;if(id==lease.actor.character_id)out.member.opt_in=request.opt_in.enabled;}
 if(dirty){SaveStateUnderTransaction(db,out.member.guild,out.state);out.state.revision++;out.changed=true;}
 auto clock=Q(db,"SELECT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)");auto now=std::stoull(clock.begin()[0]);uint64_t cost=0;for(size_t i=0;i<4;++i)if(out.state.bank.ids[i]!=UINT32_MAX)cost+=definitions.at(out.state.bank.ids[i]).tiers[out.state.bank.tiers[i]].cost;
 bool active=out.state.enabled&&(!cost||(out.state.paid.until_ms>now&&out.state.paid.until_ms-now<=INT32_MAX));if(active&&cost)out.remaining_ms=uint32_t(out.state.paid.until_ms-now);
 if(active&&cost){auto policies=Q(db,"SELECT period_ms,policy,source_sha256,source_description FROM housing_guild_trophy_billing_policy WHERE singleton=1 FOR UPDATE");TrophyBenefits::BillingPolicy policy;if(policies.RowCount()==1&&policies.begin()[3]&&policies.begin()[3][0])policy={Number(policies.begin()[0]),policies.begin()[2]?policies.begin()[2]:"",Number(policies.begin()[1])};if(!TrophyBenefits::Valid(policy)||SelectionHash(out.state,definitions,policy)!=out.state.paid.selection_hash){active=false;out.state.enabled=false;out.remaining_ms=0;out.changed=true;}}
 if(active&&out.member.opt_in)for(size_t i=0;i<4;++i)if(out.state.bank.ids[i]!=UINT32_MAX){const auto& tier=definitions.at(out.state.bank.ids[i]).tiers[out.state.bank.tiers[i]];auto current=std::find_if(sources.value.begin(),sources.value.end(),[&](const auto& source){return source.benefit==out.state.bank.ids[i]&&out.state.sources[i]&&source.source.custody==out.state.sources[i]->custody&&source.source.house==out.state.sources[i]->house&&source.source.digest==out.state.sources[i]->digest;});if(request.level>=tier.minimum_level&&current!=sources.value.end()){out.stat_items.push_back(tier.stat_item_id);out.stat_item_slots[i]=tier.stat_item_id;}}
 return {std::move(out),Error::None};
 }catch(const Failure& e){return {{},e.error};}catch(...){return {{},Error::DatabaseFailure};}}
}
#endif
